import{c as e,Q as o,j as d,m as c}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Omnigent vs cc-workspace 對照報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-27-omnigent-workspace-comparison.md","filePath":"research/reports/2026-06-27-omnigent-workspace-comparison.md","lastUpdated":1785909234000}'),r={name:"research/reports/2026-06-27-omnigent-workspace-comparison.md"};function s(a,t,n,i,l,p){return o(),d("div",null,[...t[0]||(t[0]=[c('<h1 id="omnigent-vs-cc-workspace-對照報告" tabindex="-1">Omnigent vs cc-workspace 對照報告 <a class="header-anchor" href="#omnigent-vs-cc-workspace-對照報告" aria-label="Permalink to &quot;Omnigent vs cc-workspace 對照報告&quot;">​</a></h1><p><strong>日期</strong>: 2026-06-27<br><strong>主題</strong>: Omnigent meta-harness YAML spec 與 cc-workspace <code>.claude/</code> 結構對照<br><strong>來源</strong>: github.com/omnigent-ai/omnigent（README + docs/AGENT_YAML_SPEC.md + examples/kimi_hello.yaml + omnigent/policies/builtins/cost.py）</p><hr><h2 id="_1-omnigent-yaml-schema-摘要" tabindex="-1">1. Omnigent YAML Schema 摘要 <a class="header-anchor" href="#_1-omnigent-yaml-schema-摘要" aria-label="Permalink to &quot;1. Omnigent YAML Schema 摘要&quot;">​</a></h2><h3 id="抓取成功的來源" tabindex="-1">抓取成功的來源 <a class="header-anchor" href="#抓取成功的來源" aria-label="Permalink to &quot;抓取成功的來源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>來源</th><th>URL</th><th>狀態</th></tr></thead><tbody><tr><td>README</td><td>github.com/omnigent-ai/omnigent</td><td>成功</td></tr><tr><td>AGENT_YAML_SPEC.md</td><td>github.com/omnigent-ai/omnigent/blob/main/docs/AGENT_YAML_SPEC.md</td><td>成功（部分）</td></tr><tr><td>kimi_hello.yaml</td><td>github.com/omnigent-ai/omnigent/blob/main/examples/kimi_hello.yaml</td><td>成功</td></tr><tr><td>cost.py policy</td><td>github.com/omnigent-ai/omnigent/blob/main/omnigent/policies/builtins/cost.py</td><td>成功（摘要）</td></tr><tr><td>debby/polly/scribe examples</td><td>github.com/omnigent-ai/omnigent/tree/main/examples</td><td>部分（目錄可見，內容未抓）</td></tr></tbody></table><h3 id="omnigent-agent-yaml-完整-field-清單" tabindex="-1">Omnigent Agent YAML 完整 Field 清單 <a class="header-anchor" href="#omnigent-agent-yaml-完整-field-清單" aria-label="Permalink to &quot;Omnigent Agent YAML 完整 Field 清單&quot;">​</a></h3><p><strong>Top-level fields</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>型別</th><th>說明</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>agent 識別符</td></tr><tr><td><code>description</code></td><td>string</td><td>agent 用途說明</td></tr><tr><td><code>prompt</code> / <code>instructions</code></td><td>string</td><td>system prompt / 行為指示</td></tr><tr><td><code>executor</code></td><td>object</td><td>runtime 組態（harness + model + auth）</td></tr><tr><td><code>tools</code></td><td>object map</td><td>工具定義（function / mcp / agent 三種 type）</td></tr><tr><td><code>policies</code></td><td>object map</td><td>治理規則（cost / safety / tool-access）</td></tr><tr><td><code>params</code></td><td>object</td><td>自訂參數 [unverified: 詳細型別未抓]</td></tr><tr><td><code>os_env</code></td><td>object</td><td>環境變數注入 [unverified: 詳細用法]</td></tr><tr><td><code>terminals</code></td><td>object</td><td>終端機設定 [unverified]</td></tr><tr><td><code>async</code></td><td>bool</td><td>非同步執行 [unverified]</td></tr><tr><td><code>cancellable</code></td><td>bool</td><td>允許中途取消 [unverified]</td></tr><tr><td><code>timers</code></td><td>object</td><td>排程觸發 [unverified: 詳細語法]</td></tr></tbody></table><p><strong>executor sub-fields</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>說明</th><th>已知值</th></tr></thead><tbody><tr><td><code>executor.harness</code></td><td>指定 runtime</td><td><code>claude-sdk</code>, <code>openai-agents</code>, <code>codex</code>, <code>cursor</code>, <code>kiro-native</code>, <code>pi</code>, <code>antigravity</code>, <code>qwen</code>, <code>kimi</code>, <code>copilot</code>, <code>hermes</code></td></tr><tr><td><code>executor.model</code></td><td>provider-specific model ID</td><td><code>kimi-k2-turbo</code>, <code>claude-*</code>, <code>gpt-*</code>...</td></tr><tr><td><code>executor.auth</code></td><td>認證類型</td><td><code>databricks</code>, <code>api_key</code>, <code>subscription</code>, <code>gateway</code></td></tr></tbody></table><p><strong>tools sub-fields</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>說明</th></tr></thead><tbody><tr><td><code>tools.&lt;name&gt;.type</code></td><td><code>function</code> / <code>mcp</code> / <code>agent</code></td></tr><tr><td><code>tools.&lt;name&gt;.callable</code></td><td>Python function path（type=function 時）</td></tr><tr><td><code>tools.&lt;name&gt;.url</code></td><td>MCP server endpoint（type=mcp 時）</td></tr><tr><td><code>tools.&lt;name&gt;.prompt</code></td><td>sub-agent 指示（type=agent 時）</td></tr><tr><td><code>tools.&lt;name&gt;.tools</code></td><td>子工具繼承（type=agent 時，<code>inherit</code> 關鍵字）</td></tr></tbody></table><p><strong>policies sub-fields</strong>（cost 為主要可驗證範例）:</p><table tabindex="0"><thead><tr><th>Field</th><th>說明</th></tr></thead><tbody><tr><td><code>policies.&lt;name&gt;.type</code></td><td><code>function</code></td></tr><tr><td><code>policies.&lt;name&gt;.handler</code></td><td>built-in 或自訂 Python handler path</td></tr><tr><td><code>policies.&lt;name&gt;.factory_params</code></td><td>handler 參數物件</td></tr><tr><td><code>factory_params.max_cost_usd</code></td><td>硬上限（必填，&gt;0）</td></tr><tr><td><code>factory_params.ask_thresholds_usd</code></td><td>軟檢查點清單（超越時請求許可）</td></tr><tr><td><code>factory_params.expensive_models</code></td><td>高費模型清單（觸發 downgrade）</td></tr></tbody></table><p><strong>Policy scope levels</strong>（三層，嚴格度：session &gt; agent &gt; server）:</p><ul><li>Server-wide（admin 設定）</li><li>Per-agent（developer 設定）</li><li>Per-session（user 設定，最嚴格先檢查）</li></ul><p><strong><code>after: spend &gt; $100 → pause_and_request_permission</code> 語法</strong>: [unverified — README 背景說明提及此行為概念，但確切 YAML 語法未在抓到的 spec 中找到。<code>cost_budget</code> policy + <code>ask_thresholds_usd</code> 是確認的實作機制，效果等價。]</p><hr><h2 id="_2-對照表" tabindex="-1">2. 對照表 <a class="header-anchor" href="#_2-對照表" aria-label="Permalink to &quot;2. 對照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Omnigent field</th><th>用途</th><th>workspace 對應</th><th>gap?</th></tr></thead><tbody><tr><td><code>executor.harness</code></td><td>一行換 runtime（Claude Code / Codex / Cursor / Kimi...）</td><td>無直接對應——workspace 硬綁 Claude Code harness，無 harness 切換層</td><td><strong>GAP（設計哲學差異）</strong>: workspace 基於 MHF 原則刻意單一 harness；Omnigent 為 multi-harness portability</td></tr><tr><td><code>executor.model</code></td><td>指定模型 ID</td><td><code>multi-mode-skill</code> §1 位置數判準 → <code>model=haiku/sonnet/opus/fable</code>；<code>subagent-strategy.md</code> 模型選擇</td><td>覆蓋：workspace 動態路由，Omnigent 靜態宣告</td></tr><tr><td><code>executor.auth</code></td><td>認證（api_key / databricks / subscription / gateway）</td><td>未在 CLAUDE.md / rules 中顯式設定；由 Claude Code CLI 環境變數處理</td><td>小 gap：workspace 無 auth 層抽象，靠 CLI 環境設定</td></tr><tr><td><code>tools.&lt;name&gt;.type: function</code></td><td>自訂 Python function 工具</td><td>Bash hook / scripts/*.py；<code>allowed-tools</code> SKILL frontmatter</td><td>部分覆蓋：workspace 工具是靜態清單，無 Python callable 動態注入</td></tr><tr><td><code>tools.&lt;name&gt;.type: mcp</code></td><td>MCP server endpoint</td><td>Claude Code 內建 MCP 支援（.claude/settings 或 CLI 設定）</td><td>覆蓋：MCP 支援存在，但非 YAML per-agent 宣告</td></tr><tr><td><code>tools.&lt;name&gt;.type: agent</code></td><td>sub-agent 工具（nested agent as tool）</td><td><code>AGENTS.md</code> dispatch table + <code>subagent-strategy.md</code> fan-out</td><td>覆蓋：功能等價，但 workspace 用 prompt injection 而非 YAML 宣告</td></tr><tr><td><code>tools.&lt;name&gt;.tools: inherit</code></td><td>子 agent 繼承父工具</td><td>無 inherit 語法；子 agent 需 parent prompt 顯式傳遞（handoff contract）</td><td><strong>GAP</strong>: workspace 要求 parent 顯式注入全部 context，無 <code>inherit</code> 快捷</td></tr><tr><td><code>policies.&lt;name&gt;.handler</code></td><td>治理規則 handler（Python callable）</td><td><code>.claude/hooks/block-dangerous.sh</code>（PreToolUse）; <code>pre-push-cost.sh</code>（PostToolUse）; <code>protect-sensitive-files.sh</code></td><td>部分覆蓋：workspace 用 bash hooks，Omnigent 用 Python policy handler</td></tr><tr><td><code>policies.budget.factory_params.max_cost_usd</code></td><td>硬性 USD 上限，超限拒絕操作或要求降級</td><td><code>model-selection-grid.md</code> 提及 <code>--max-budget-usd</code>（Claude Code CLI print mode GA）；<code>pre-push-cost.sh</code> 紀錄 cost，但無自動阻斷</td><td><strong>GAP（高 ROI）</strong>: workspace 無 mid-session cost gate；只有 push 後的 cost 記錄 + 事後監控</td></tr><tr><td><code>policies.budget.factory_params.ask_thresholds_usd</code></td><td>軟檢查點，超越時請求許可</td><td>無對應機制</td><td><strong>GAP（高 ROI）</strong>: workspace 無 per-session 軟成本閾值提醒</td></tr><tr><td><code>policies.budget.factory_params.expensive_models</code></td><td>高費模型清單，超限強制 downgrade</td><td><code>multi-mode-skill</code> 位置數判準（Haiku→Sonnet→Opus 路由）；<code>context-management.md</code> token budget 軟限</td><td>覆蓋：workspace 有 upfront model routing，無動態 downgrade gate</td></tr><tr><td>Policy scope 三層（server/agent/session）</td><td>不同作用域的治理策略覆蓋</td><td><code>core.md</code> APPLY §不可逆例外（session 級確認）；hooks 作用於所有 tool calls（server 層等價）；無 per-agent policy scope</td><td>小 gap：workspace 無明確 per-agent policy scope</td></tr><tr><td><code>name</code> + <code>description</code></td><td>agent 識別與說明</td><td>SKILL.md frontmatter（<code>name</code>, <code>description</code>, <code>roster-domain</code>）</td><td>覆蓋</td></tr><tr><td><code>prompt</code> / <code>instructions</code></td><td>agent system prompt</td><td>SKILL.md 正文 + sub-agent prompt injection（handoff contract）</td><td>覆蓋</td></tr><tr><td><code>params</code></td><td>自訂 agent 參數</td><td>SKILL.md `</td><td>參數</td></tr><tr><td><code>os_env</code></td><td>環境變數</td><td><code>.env</code> + <code>session-init.sh</code></td><td>覆蓋（非 per-agent）</td></tr><tr><td><code>timers</code> / 排程</td><td>定時觸發</td><td><code>/schedule</code> routine + <code>CronCreate</code> / <code>ScheduleWakeup</code>（<code>multi-mode-skill</code> §0）</td><td>覆蓋（CLI 本機限定）</td></tr><tr><td><code>async</code> + <code>cancellable</code></td><td>非同步執行與取消</td><td><code>run_in_background: true</code>（Bash tool）；<code>pause_turn</code>（agent control）</td><td>覆蓋</td></tr><tr><td><code>terminals</code></td><td>終端機設定</td><td>Claude Code CLI 終端即 terminal，無額外配置</td><td>無對應（不適用）</td></tr></tbody></table><hr><h2 id="_3-可借鏡點-按-roi-排序-≤3" tabindex="-1">3. 可借鏡點（按 ROI 排序，≤3） <a class="header-anchor" href="#_3-可借鏡點-按-roi-排序-≤3" aria-label="Permalink to &quot;3. 可借鏡點（按 ROI 排序，≤3）&quot;">​</a></h2><h3 id="p1-最高-roi-—-mid-session-cost-gate" tabindex="-1">P1（最高 ROI）— Mid-session Cost Gate <a class="header-anchor" href="#p1-最高-roi-—-mid-session-cost-gate" aria-label="Permalink to &quot;P1（最高 ROI）— Mid-session Cost Gate&quot;">​</a></h3><p><strong>Omnigent 機制</strong>: <code>policies.budget</code> + <code>ask_thresholds_usd: [3.00]</code> + <code>max_cost_usd: 5.00</code><br> 在 session 進行中，累計消費跨越軟閾值時自動請求使用者許可；跨越硬上限時拒絕操作。</p><p><strong>workspace 現狀</strong>: 只有 <code>pre-push-cost.sh</code>（push 後記錄，不阻斷）+ <code>--max-budget-usd</code>（CLI print mode 專用，非互動 session）。<code>context-management.md</code> 的 token budget 是軟性行為信號，非 code-enforced gate。</p><p><strong>借鏡方向</strong>: PreToolUse hook 讀取 <code>~/.claude/usage.db</code> 當前 session 累計 cost，超過設定閾值（如 $5）時 <code>exit 2</code> + 訊息「已消費 $X.XX，是否繼續？」。等同 Omnigent 的 <code>ask_thresholds_usd</code> 行為，不需要引入 Omnigent 依賴。</p><p><strong>實作成本</strong>: 中（1 個新 hook，約 50 行 bash/python；需驗證 <code>usage.db</code> 即時讀取精度）。</p><hr><h3 id="p2-高-roi-—-tools-inherit-語法等價-sub-agent-tool-context-protocol" tabindex="-1">P2（高 ROI）— <code>tools: inherit</code> 語法等價：Sub-agent Tool Context Protocol <a class="header-anchor" href="#p2-高-roi-—-tools-inherit-語法等價-sub-agent-tool-context-protocol" aria-label="Permalink to &quot;P2（高 ROI）— `tools: inherit` 語法等價：Sub-agent Tool Context Protocol&quot;">​</a></h3><p><strong>Omnigent 機制</strong>: <code>tools.&lt;sub-agent&gt;.tools: inherit</code> — 子 agent 自動繼承父 agent 的工具集，無需 parent 重複注入。</p><p><strong>workspace 現狀</strong>: Handoff Contract 要求 parent 顯式傳遞「allowed-tools + 全部必要 context」給子 agent（<code>subagent-strategy.md §任務契約</code>）。這是正確的隔離設計，但造成 prompt boilerplate。</p><p><strong>借鏡方向</strong>: 在 AGENTS.md §2 dispatch table 中為每個標準 agent 定義 <code>allowed-tools</code> 清單（已有部分實作於 SKILL.md frontmatter）；建立「agent inherit profile」概念（如 <code>inherits: researcher-base</code>），讓 handoff contract 可以引用 profile 而非每次全列。不必引入 Omnigent，僅需 workspace 慣例標準化。</p><p><strong>實作成本</strong>: 低（文件整理 + AGENTS.md 格式擴充；不改動 hooks）。</p><hr><h3 id="p3-中-roi-—-policy-scope-三層顯式化" tabindex="-1">P3（中 ROI）— Policy Scope 三層顯式化 <a class="header-anchor" href="#p3-中-roi-—-policy-scope-三層顯式化" aria-label="Permalink to &quot;P3（中 ROI）— Policy Scope 三層顯式化&quot;">​</a></h3><p><strong>Omnigent 機制</strong>: server / agent / session 三層 policy 優先序；最嚴格者優先。</p><p><strong>workspace 現狀</strong>: hooks 是 server 層（全域，所有 tool calls）；<code>core.md §APPLY 不可逆例外</code> 是 session 層；per-agent policy 無顯式定義。</p><p><strong>借鏡方向</strong>: 在 AGENTS.md §5（Harness vs Body）或新增 §Policy Scope 章節，顯式文件化三層 policy 優先序（server = hooks；agent = SKILL.md allowed-tools + 紅線；session = 不可逆確認）。不需改 code，僅需 framing 更清楚。對新 skill 設計有指引價值，提升 harness 可解釋性。</p><p><strong>實作成本</strong>: 低（文件，~20 行）。</p><hr><h2 id="_4-不適用-已覆蓋項" tabindex="-1">4. 不適用 / 已覆蓋項 <a class="header-anchor" href="#_4-不適用-已覆蓋項" aria-label="Permalink to &quot;4. 不適用 / 已覆蓋項&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Omnigent feature</th><th>判斷</th><th>原因</th></tr></thead><tbody><tr><td><code>executor.harness</code> 多 runtime</td><td>不適用</td><td>workspace 基於 MHF 原則：Claude Code post-training byte-level 過擬合，跨 harness 是效能崩塌風險（<code>harness-design.md §反模式</code>）。Omnigent 的核心價值命題在此與 workspace 哲學對立。</td></tr><tr><td><code>executor.auth</code> gateway / subscription 支援</td><td>不適用</td><td>workspace 單一 Anthropic API，無多供應商需求</td></tr><tr><td><code>tools.type: function</code> Python callable 注入</td><td>已覆蓋</td><td>workspace 用 <code>scripts/*.py</code> + Bash tool；效果等價，MHF 下無需動態 callable</td></tr><tr><td><code>prompt</code> / system instructions</td><td>已覆蓋</td><td>SKILL.md + AGENTS.md + CLAUDE.md 三層</td></tr><tr><td><code>timers</code> 排程</td><td>已覆蓋</td><td><code>/schedule</code> + <code>CronCreate</code> / <code>ScheduleWakeup</code></td></tr></tbody></table><hr><h2 id="_5-結論" tabindex="-1">5. 結論 <a class="header-anchor" href="#_5-結論" aria-label="Permalink to &quot;5. 結論&quot;">​</a></h2><p><strong>有值得開 EVOLUTION-QUEUE 提案的 gap</strong>: 是，一個高優先項。</p><h3 id="建議提案-pre-session-cost-gate-hook" tabindex="-1">建議提案：<code>pre-session-cost-gate</code> hook <a class="header-anchor" href="#建議提案-pre-session-cost-gate-hook" aria-label="Permalink to &quot;建議提案：`pre-session-cost-gate` hook&quot;">​</a></h3><p><strong>問題</strong>: workspace 目前無 mid-session cost gate，Fable 5 / Opus 4.8 長任務可能在使用者無感知下消費 $10–$30（model-selection-grid.md §AA-Briefcase）。<code>pre-push-cost.sh</code> 是事後紀錄，<code>--max-budget-usd</code> 僅 print mode。</p><p><strong>方案</strong>: 新增 <code>PreToolUse</code> hook，讀取 <code>~/.claude/usage.db</code> 當前 session cost，超過 <code>CLAUDE_SESSION_COST_LIMIT</code>（建議預設 $5，可覆寫）時 <code>exit 2</code> + 提示使用者確認。可設 <code>ask_thresholds_usd</code> 等價的軟閾值（如 $3 提示、$8 硬阻斷）。</p><p><strong>驗收條件</strong>: session cost 達 $3 時自動顯示提示（可繼續），達 $5 時 block 並要求手動確認；<code>CLAUDE_SKIP_COST_GATE=1</code> 可旁路（admin override）。</p><p><strong>ROI</strong>: 防止單次意外超支，特別是 agentic overnight 任務；與 Omnigent 治理設計對齊；不引入任何新依賴（<code>usage.db</code> 已有，<code>pricing.py</code> 已有）。</p><p><strong>開提案路徑</strong>: <code>research/EVOLUTION-QUEUE.md</code> → 標題 <code>[COST-GATE] mid-session cost threshold hook</code>。</p><hr><p><em>來源抓取狀態</em>:</p><ul><li>github.com/omnigent-ai/omnigent README: 成功</li><li>docs/AGENT_YAML_SPEC.md: 成功（部分欄位 [unverified] 標注）</li><li>examples/kimi_hello.yaml: 成功</li><li>omnigent/policies/builtins/cost.py: 成功（摘要）</li><li><code>after: spend &gt; $100 → pause_and_request_permission</code> 確切 YAML 語法: [unverified]（等價實作機制 <code>ask_thresholds_usd</code> 已確認）</li></ul>',55)])])}const g=e(r,[["render",s]]);export{m as __pageData,g as default};
